const initial={items:clone(SEED.items),chassis:clone(SEED.chassis),freight:clone(SEED.freight),disabled:[],users:[{id:'rep-a',name:'Jordan Lee',role:'Sales representative',territory:'North region',active:true},{id:'rep-b',name:'Alex Morgan',role:'Sales representative',territory:'South region',active:true},{id:'admin',name:'HQ Administrator',role:'Administrator',territory:'Headquarters',active:true}],quotes:[],logs:[]};
const samples=[['rep-a','3001','Northfield Public Works','MT4H','Finalized','2026-09-29'],['rep-a','3002','Lakeside Street Services','MS5H','Draft','2026-09-29'],['rep-a','3003','Riverbend Municipality','MT4H','Draft','2026-09-30'],['rep-b','3004','Southridge Public Works','MS5H','Finalized','2026-09-28'],['rep-a','3005','Westhaven Maintenance','MT4H','Finalized','2026-09-28']];
for(const [owner,no,customer,model,status,date] of samples){let base=SEED.items.find(x=>x.isBase&&x.model===model);initial.quotes.push({id:crypto.randomUUID(),owner,no,customer,model,status,date,version:1,total:base.msrp+6015,state:{quoteSeq:no,toCompany:customer,model,date,basis:'MSRP (Commercial)',salesRep:initial.users.find(u=>u.id===owner).name,baseQty:1,freight:6015},catalog:clone(SEED.items),chassis:clone(SEED.chassis),freight:clone(SEED.freight)});}
let db;try{db=JSON.parse(localStorage.getItem('odra-demo-v1'))||clone(initial)}catch{db=clone(initial)}
for(const account of db.users){if(typeof account.officeEmail!=='string')account.officeEmail='';}
let user=null,selectedPersona='rep-a',page='dashboard',current=null,filter='All statuses',search='';
function persist(){try{localStorage.setItem('odra-demo-v1',JSON.stringify(db))}catch{toast('Browser storage is full. Changes remain available for this visit.')}}
function audit(action){db.logs.unshift({action,by:user?.name||'Demo',at:new Date().toLocaleString()});persist()}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function initials(name){return name.split(' ').slice(0,2).map(x=>x[0]).join('')}
function login(){user=null;$('#app').innerHTML=`<div class="login"><section class="login-story"><div class="brand"><img src="logo.jpg" alt="ODRA Road Sweepers"></div><h1>Built for the road.<br><span>Ready for the sale.</span></h1><p>Your workspace for configuring sweepers, preparing quotations, and keeping every customer conversation moving.</p><div class="steps"><div class="step"><span>01</span> Configure with centrally managed pricing</div><div class="step"><span>02</span> Create and download your quotations</div><div class="step"><span>03</span> Keep every version in one place</div></div><footer>ODRA ROAD SWEEPERS &nbsp; / &nbsp; SALES PORTAL</footer></section><section class="login-form"><div class="login-inner"><span class="pill">INTERACTIVE DEMO</span><h2>Welcome to your workspace</h2><p>Use your registered office email to sign in with Microsoft.</p><section class="company-login" aria-labelledby="company-login-title"><h3 id="company-login-title">Company sign-in</h3><div class="field"><label for="office-login-email">Office email</label><input id="office-login-email" type="email" autocomplete="username" placeholder="name@yourcompany.com" aria-describedby="microsoft-status"></div><button class="primary microsoft-signin" disabled aria-describedby="microsoft-status">Continue with Microsoft</button><p id="microsoft-status" class="signin-pending">Microsoft sign-in is not connected yet. An office-email entry alone does not verify identity or grant access.</p><p class="signin-rule">Production access will require Microsoft verification and an active, registered sales account.</p></section><details class="demo-access"><summary>Explore sample demo accounts</summary><p class="muted">Preview only · no Microsoft authentication</p>${db.users.filter(u=>u.active).map(u=>`<button class="persona ${selectedPersona===u.id?'selected':''}" data-persona="${u.id}" aria-pressed="${selectedPersona===u.id}"><span class="avatar">${initials(u.name)}</span><span class="persona-text"><b>${esc(u.name)}</b><small>${esc(u.role)} · ${esc(u.territory)}</small></span>${icon(u.role==='Administrator'?'shield':'users')}</button>`).join('')}<button class="primary" id="enter">Open demo workspace</button></details><p class="login-note">Demo access does not provide company authentication. The Microsoft connection and server-side access checks are pending. Demo changes are saved only in this browser. Please use fictional customer information.</p></div></section></div>`;document.querySelectorAll('[data-persona]').forEach(b=>b.onclick=()=>{selectedPersona=b.dataset.persona;login();document.querySelector('.demo-access').open=true});$('#enter').onclick=()=>enter(selectedPersona)}
function enter(id){const u=db.users.find(x=>x.id===id&&x.active);if(!u){toast('This sample account is inactive. Choose another account.');return}user=u;page='dashboard';current=null;search='';filter='All statuses';render()}
function owned(){return db.quotes.filter(q=>q.owner===user.id)}
function nav(p){if(page==='builder'&&current?.status==='Draft'&&!confirm('Leave this quote? Save your draft first to keep any changes.'))return;page=p;current=null;search='';filter='All statuses';render()}
const titles={dashboard:'Overview',quotes:'My quotations',builder:'Quote Builder',models:'Models & pricing',options:'Enhancements & parts',users:'Sales representatives',freight:'Freight rates',audit:'Activity log'};
function render(){if(!user)return login();if(!user.active)return login();const admin=user.role==='Administrator';if(!admin&&['models','options','users','freight','audit'].includes(page)){page='dashboard';toast('The admin panel is available only in the administrator demo.')}const navs=admin?[['dashboard','grid','Overview'],['models','box','Models & pricing'],['options','plus','Enhancements & parts'],['freight','truck','Freight rates'],['users','users','Sales representatives'],['audit','clock','Activity log']]:[['dashboard','grid','Overview'],['quotes','file','My quotations'],['builder','plus','Create quotation']];
$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><img src="logo.jpg" alt="ODRA Road Sweepers"></div><div class="eyebrow">${admin?'Headquarters':'Sales workspace'}</div><div class="navlabel">${admin?'ADMINISTRATION':'WORKSPACE'}</div><nav>${navs.map(([p,i,t])=>`<button title="${t}" class="navbtn ${page===p?'active':''}" data-nav="${p}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebottom"><span class="pill">DEMO ENVIRONMENT</span><p>Sample data · This browser only</p><button class="navbtn" id="logout">${icon('logout')}<span>Back to login</span></button></div></aside><main class="main"><header class="topbar"><div class="crumb">ODRA Portal <span>/</span> <b>${titles[page]}</b></div><div class="profile"><div class="identity"><b>${esc(user.name)}</b><small>${admin?'Administrator':user.territory}</small></div><span class="avatar">${initials(user.name)}</span><label><span class="switchlabel">Demo account</span><select id="switcher" aria-label="Switch demo account"><option value="">Login screen</option>${db.users.filter(u=>u.active).map(u=>`<option value="${u.id}" ${u.id===user.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label></div></header><div class="content ${page==='builder'?'buildercontent':''}" id="content"></div></main></div>`;
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>b.dataset.nav==='builder'?newQuote():nav(b.dataset.nav));if($('#logout'))$('#logout').onclick=login;$('#switcher').onchange=e=>{if(page==='builder'&&!confirm('Switch accounts? Unsaved quote changes will be lost.')){e.target.value=user.id;return}e.target.value?enter(e.target.value):login()};
if(page==='dashboard'||page==='quotes')admin?adminDashboard():dashboard();if(page==='builder')builder();if(page==='models')models();if(page==='options')options();if(page==='users')users();if(page==='freight')freight();if(page==='audit')activity();}
function heading(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function stat(label,value,sub,i,accent=false){return `<div class="stat ${accent?'accent':''}"><div class="statlabel">${label}${icon(i)}</div><strong>${value}</strong><small>${sub}</small></div>`}
function dashboard(){const qs=owned();$('#content').innerHTML=heading(page==='quotes'?'My quotations':`Good to see you, ${esc(user.name.split(' ')[0])}.`,page==='quotes'?'Your saved drafts, finalized quotes, and previous versions.':'Your quotations and next steps, all in one place.',`<button class="primary" id="new">${icon('plus')}Create quotation</button>`)+`<div class="stats">${stat('My quotations',qs.length,'Across all versions','file',true)}${stat('Drafts',qs.filter(q=>q.status==='Draft').length,'Ready to pick up where you left off','edit')}${stat('Finalized',qs.filter(q=>q.status==='Finalized').length,'Ready to download','check')}${stat('Quoted value',money(qs.filter(q=>q.status==='Finalized').reduce((a,q)=>a+q.total,0)),'Finalized quotations · USD','dollar')}</div><div class="workspace"><section class="card"><div class="cardhead"><div><h2>${page==='quotes'?'Quote history':'Recent quotations'}</h2><p>Only quotations belonging to this sample account.</p></div><span class="pill">${qs.length} quotes</span></div><div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Search quotations" placeholder="Search quote number, customer, or model"></div><select id="filter" aria-label="Filter status"><option>All statuses</option><option>Draft</option><option>Finalized</option></select></div><div id="quote-table"></div><div class="cardfoot">Saved values are retained when the master price changes.</div></section><aside class="rightaside"><div class="card"><div class="asideblock"><h3>Current model pricing</h3><p>Available for your next quotation</p>${db.items.filter(x=>x.isBase&&!db.disabled.includes(x.model)).map(x=>`<div class="modelrow"><div><span class="miniicon">${icon('truck')}</span><div><b>${esc(x.model)}</b><small>Mechanical broom sweeper</small></div></div><b>${money(x.msrp)}</b></div>`).join('')}<small class="muted">Base MSRP · before enhancements & freight</small></div></div><div class="callout"><div class="eyebrow">TRY THE WORKFLOW</div><h3 style="margin-top:12px">One quote. Every detail.</h3><p>Create a quote, save it as a draft, then finalize and download your PDF.</p><button id="trynew">${icon('plus')}Create quotation</button></div></aside></div>`;$('#new').onclick=$('#trynew').onclick=newQuote;$('#search').oninput=e=>{search=e.target.value;quoteTable()};$('#filter').onchange=e=>{filter=e.target.value;quoteTable()};quoteTable()}
function quoteTable(){let qs=owned().filter(q=>(filter==='All statuses'||q.status===filter)&&`${q.no} ${q.customer} ${q.model}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.no.localeCompare(a.no)||b.version-a.version);$('#quote-table').innerHTML=qs.length?`<div class="tablewrap"><table><thead><tr><th>Quote / Customer</th><th>Model</th><th>Status</th><th class="number">Total (USD)</th><th></th></tr></thead><tbody>${qs.map(q=>`<tr><td><button class="quotelink" data-open="${q.id}">Q-${esc(q.no)} <span class="muted">· v${q.version}</span></button><small>${esc(q.customer)}</small></td><td><strong>${esc(q.model)}</strong><small>${esc(q.date)}</small></td><td><span class="pill ${q.status.toLowerCase()}">${q.status}</span></td><td class="number">${money(q.total)}</td><td><button class="small" data-open="${q.id}">${q.status==='Draft'?'Continue':'View quote'}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No quotations match your search.</div>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openQuote(b.dataset.open))}
function newQuote(){if(!db.items.some(x=>x.isBase&&!db.disabled.includes(x.model))){toast('No active models. Activate a model in the admin demo first.');return}current={id:crypto.randomUUID(),owner:user.id,no:String(Math.max(3000,...db.quotes.map(q=>Number(q.no)))+1),version:1,status:'Draft',date:new Date().toISOString().slice(0,10)};page='builder';render()}
function openQuote(id){const q=owned().find(x=>x.id===id);if(!q)return toast('Quotation unavailable for this account.');current=clone(q);page='builder';render()}
function builder(){if(!current)return newQuote();const final=current.status==='Finalized';$('#content').innerHTML=heading(`Quotation Q-${current.no}`,`Version ${current.version} · ${final?'Finalized · saved pricing retained':'Draft · '+esc(user.name)}`,`<div class="actions"><button id="back">My quotations</button>${final?'<button id="revise">Create revision</button>':'<button id="save">Save draft</button><button class="primary" id="finalize">Finalize quote</button>'}</div>`)+`<iframe id="builder" title="ODRA Quote Builder and quotation preview" src="builder.html"></iframe>`;$('#back').onclick=()=>nav('quotes');if(final)$('#revise').onclick=()=>{const prior=current;current=clone(prior);current.id=crypto.randomUUID();current.version=Math.max(...owned().filter(q=>q.no===prior.no).map(q=>q.version))+1;current.status='Draft';current.date=new Date().toISOString().slice(0,10);render();toast('New draft revision created with saved pricing. Previous version is preserved.')} ;else{$('#save').onclick=()=>saveQuote(false);$('#finalize').onclick=()=>saveQuote(true)}$('#builder').onload=()=>{const win=$('#builder').contentWindow;if(!win.demoLoad)return toast('Quote Builder could not load. Please reopen this quote.');win.demoLoad({state:current.state||{quoteSeq:current.no,salesRep:user.name,model:db.items.find(x=>x.isBase&&!db.disabled.includes(x.model)).model},items:current.catalog||db.items.filter(x=>!db.disabled.includes(x.model)),chassis:current.chassis||db.chassis,freight:current.freight||db.freight,readonly:final});};}
function saveQuote(final){let frame=$('#builder')?.contentWindow;if(!frame?.demoSnapshot)return;let data=frame.demoSnapshot();if(!data.state.toCompany.trim()){toast('Enter a customer company name before saving.');frame.document.getElementById('toCompany').focus();return}if(final&&!confirm('Finalize this quotation? Its saved values will be preserved. Later changes will use a new revision.'))return;Object.assign(current,{...data,customer:data.state.toCompany,model:data.state.model,date:data.state.date,status:final?'Finalized':'Draft'});let idx=db.quotes.findIndex(q=>q.id===current.id);if(idx<0)db.quotes.push(clone(current));else db.quotes[idx]=clone(current);audit(`Q-${current.no} v${current.version} ${final?'finalized':'saved as draft'}`);toast(final?'Quotation finalized. Download the PDF in the Quote Builder.':'Draft saved to My quotations.');if(final)render()}
function adminDashboard(){const active=db.items.filter(x=>x.isBase&&!db.disabled.includes(x.model));$('#content').innerHTML=heading('Headquarters overview','Manage the catalogue and access for your sales team.',`<span class="pill">${icon('shield')}Administrator</span>`)+`<div class="notice">${icon('shield')}Demo administration. Changes apply across sample accounts in this browser.</div><div class="stats">${stat('Active models',active.length,'Available to sales representatives','box',true)}${stat('Enhancements',db.items.filter(x=>!x.isBase).length,'Model-specific options & parts','plus')}${stat('Sales representatives',db.users.filter(u=>u.id!=='admin'&&u.active).length,'Active sample accounts','users')}${stat('Catalogue updates',db.logs.length,'Recorded in the activity log','clock')}</div><div class="catalog"><div class="card modelcard"><span class="miniicon">${icon('box')}</span><h2>Product & pricing masters</h2><p>Manage base prices, configurations, enhancements and freight from one central workspace.</p><button class="primary" data-go="models">Manage models & pricing</button></div><div class="card modelcard"><span class="miniicon">${icon('users')}</span><h2>Your sales team</h2><p>Add or deactivate sample representatives and explore their individual quotation workspace.</p><button data-go="users">Manage sales representatives</button></div></div><div class="notice" style="margin-top:23px">${icon('clock')}Changes affect new quotations. Saved drafts and finalized versions keep their price snapshots.</div>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go))}
function models(){$('#content').innerHTML=heading('Models & pricing','Maintain the catalogue used by every sales representative.',`<button class="primary" id="addmodel">${icon('plus')}Add model</button>`)+`<div class="notice">${icon('clock')}Updated prices apply to new quotations. Existing saved quotes retain their original values.</div><div class="catalog">${db.items.filter(x=>x.isBase).map(x=>`<article class="card modelcard"><div class="modeltop"><span class="eyebrow">MECHANICAL BROOM SWEEPER</span><span class="pill ${db.disabled.includes(x.model)?'':'active'}">${db.disabled.includes(x.model)?'Inactive':'Active'}</span></div><h2>${esc(x.model)}</h2><p>${esc(x.desc.slice(0,220))}${x.desc.length>220?'…':''}</p><div class="pricegrid"><div><small>Base MSRP</small><b>${money(x.msrp)}</b></div><div><small>Co-op list</small><b>${money(x.swList)}</b></div><div><small>Co-op net</small><b>${money(x.swNet)}</b></div></div><small class="muted">${db.chassis.filter(c=>c.startsWith(x.model+' -')).length} configurations · ${db.items.filter(i=>i.model===x.model&&!i.isBase).length} enhancements</small><footer><button data-edit="${esc(x.model)}">${icon('edit')}Edit model & prices</button><button class="ghost" data-toggle="${esc(x.model)}">${db.disabled.includes(x.model)?'Activate':'Deactivate'}</button></footer></article>`).join('')}</div>`;$('#addmodel').onclick=()=>modelModal();document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>modelModal(b.dataset.edit));document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{let m=b.dataset.toggle;db.disabled.includes(m)?db.disabled=db.disabled.filter(x=>x!==m):db.disabled.push(m);audit(`${m} availability changed`);models();toast('Model availability updated for new quotes.')})}
function field(label,id,value='',type='text',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra} required></div>`}
function modal(title,sub,body,onSave){const d=$('#modal');d.innerHTML=`<form id="editform"><h2>${title}</h2><p>${sub}</p>${body}<footer><button type="button" id="cancel">Cancel</button><button type="submit" class="primary">Save changes</button></footer></form>`;$('#cancel').onclick=()=>d.close();$('#editform').onsubmit=e=>{e.preventDefault();if(onSave(new FormData(e.target))!==false)d.close()};d.showModal()}
function modelModal(name){let x=db.items.find(i=>i.isBase&&i.model===name)||{model:'',desc:'',msrp:0,swList:0,swNet:0};modal(name?'Edit '+esc(name):'Add a model','Prices are in USD. Changes become available for new quotations.',field('Model code','model',x.model,'text',name?'readonly':'maxlength="24" pattern="[A-Za-z0-9 -]+"')+`<div class="field"><label for="desc">Description</label><textarea id="desc" name="desc" required rows="3">${esc(x.desc)}</textarea></div><div class="fieldgrid">`+field('Base MSRP','msrp',x.msrp,'number','min="0" step="1"')+field('Co-op list price','swList',x.swList,'number','min="0" step="1"')+field('Co-op net price','swNet',x.swNet,'number','min="0" step="1"')+`</div><div class="field"><label for="configs">Configurations (one per line)</label><textarea id="configs" name="configs" rows="3" required>${esc(name?db.chassis.filter(c=>c.startsWith(name+' -')).map(c=>c.slice(name.length+3)).join('\n'):'Standard chassis')}</textarea></div>`,f=>{let m=f.get('model').trim();if(!name&&db.items.some(i=>i.model.toLowerCase()===m.toLowerCase())){toast('That model code already exists.');return false}let values={model:m,desc:f.get('desc').trim(),msrp:+f.get('msrp'),swList:+f.get('swList'),swNet:+f.get('swNet'),isBase:true,cat:'BASE UNIT'};if(name)Object.assign(x,values);else db.items.push(values);db.chassis=db.chassis.filter(c=>!c.startsWith(m+' -')).concat(f.get('configs').split('\n').map(c=>c.trim()).filter(Boolean).map(c=>m+' - '+c));audit(`${m} model and pricing ${name?'updated':'added'}`);models();toast('Model saved. New quotes will use these values.')})}
function options(){$('#content').innerHTML=heading('Enhancements & parts','Model-specific options included in the Quote Builder.',`<button class="primary" id="addoption">${icon('plus')}Add enhancement</button>`)+`<section class="card"><div class="tablewrap"><table><thead><tr><th>Model / Category</th><th>Description</th><th class="number">MSRP</th><th></th></tr></thead><tbody>${db.items.map((x,i)=>x.isBase?'':`<tr><td><strong>${esc(x.model)}</strong><small>${esc(x.cat)}</small></td><td style="white-space:normal;min-width:220px">${esc(x.desc)}</td><td class="number">${money(x.msrp)}</td><td><button data-opt="${i}" class="small">Edit</button> <button data-remove="${i}" class="small danger">Remove</button></td></tr>`).join('')}</tbody></table></div></section>`;$('#addoption').onclick=()=>optionModal();document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>optionModal(+b.dataset.opt));document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const i=+b.dataset.remove;if(confirm('Remove this enhancement from new quotations? Saved quotations will keep it.')){audit(`Enhancement removed: ${db.items[i].desc}`);db.items.splice(i,1);persist();options()}})}
function optionModal(idx){let x=db.items[idx]||{model:'MT4H',cat:'PARTS',desc:'',msrp:0,swList:0,swNet:0};modal('Enhancement details','Assign the option to a model and set its prices.',`<div class="field"><label for="omodel">Model</label><select name="model" id="omodel">${db.items.filter(i=>i.isBase).map(i=>`<option ${i.model===x.model?'selected':''}>${esc(i.model)}</option>`).join('')}</select></div>`+field('Category','cat',x.cat)+field('Description','desc',x.desc)+`<div class="fieldgrid">`+field('MSRP','msrp',x.msrp,'number','min="0"')+field('Co-op list','swList',x.swList,'number','min="0"')+field('Co-op net','swNet',x.swNet,'number','min="0"')+`</div>`,f=>{let val=Object.fromEntries(f);for(let k of ['msrp','swList','swNet'])val[k]=+val[k];val.isBase=false;if(idx===undefined)db.items.push(val);else db.items[idx]=val;audit(`Enhancement saved: ${val.desc}`);options();toast('Enhancement saved for new quotes.')})}
function normalizeOfficeEmail(value){return String(value??'').trim().toLowerCase();}
function validateOfficeEmail(value,accountId){
 const email=normalizeOfficeEmail(value);
 if(!email||email.length>254||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return {error:'Enter a valid office email address.'};
 if(db.users.some(u=>u.id!==accountId&&normalizeOfficeEmail(u.officeEmail)===email))return {error:'This office email is already assigned to another account.'};
 return {email};
}
function users(){
 $('#content').innerHTML=heading('Sales representatives','Manage representative details and their registered office email.',`<button class="primary" id="adduser">${icon('plus')}Add representative</button>`)+`<div class="notice">${icon('shield')}Microsoft sign-in is not connected. These demo records do not grant production access.</div><section class="card"><div class="tablewrap"><table><thead><tr><th>Representative</th><th>Office email</th><th>Territory</th><th>Demo status</th><th></th></tr></thead><tbody>${db.users.filter(u=>u.id!=='admin').map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.role)}</small></td><td>${u.officeEmail?`<span class="office-email">${esc(u.officeEmail)}</span><small>Microsoft verification pending</small>`:'<span class="pill draft">Email required</span>'}</td><td>${esc(u.territory)}</td><td><span class="pill ${u.active?'active':''}">${u.active?'Active':'Inactive'}</span></td><td><button data-edit-user="${u.id}" class="small">Edit details</button> <button data-user="${u.id}" class="small">${u.active?'Deactivate':'Activate'}</button></td></tr>`).join('')}</tbody></table></div><div class="cardfoot">Use a unique office email for each representative. Email changes keep the same representative and quote history.</div></section>`;
 $('#adduser').onclick=()=>representativeModal();
 document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>representativeModal(b.dataset.editUser));
 document.querySelectorAll('[data-user]').forEach(b=>b.onclick=()=>{let u=db.users.find(x=>x.id===b.dataset.user);u.active=!u.active;audit(`${u.name} ${u.active?'activated':'deactivated'}`);render()});
}
function representativeModal(id){
 const account=id?db.users.find(u=>u.id===id):null;
 if(id&&!account)return;
 modal(account?'Edit representative':'Add representative','Register the office email this person will use for Microsoft sign-in. Authentication is not connected yet.',field('Full name','name',account?.name||'')+field('Office email','officeEmail',account?.officeEmail||'','email','maxlength="254" autocomplete="email" placeholder="name@yourcompany.com"')+field('Territory','territory',account?.territory||'')+'<p id="email-error" class="form-error" role="alert" hidden></p>',f=>{
  const result=validateOfficeEmail(f.get('officeEmail'),id);
  if(result.error){const error=document.getElementById('email-error');error.hidden=false;error.textContent=result.error;document.getElementById('officeEmail').focus();return false;}
  const values={name:String(f.get('name')).trim(),territory:String(f.get('territory')).trim(),officeEmail:result.email};
  if(!values.name||!values.territory){toast('Enter a name and territory.');return false;}
  if(account)Object.assign(account,values);else db.users.push({id:crypto.randomUUID(),...values,role:'Sales representative',active:true});
  audit(`Representative ${account?'updated':'added'}: ${values.name}`);render();toast('Representative and office email saved in this browser.');
 });
}

function freight(){$('#content').innerHTML=heading('Freight rates','Destination estimates used by the existing territory calculation.')+`<section class="card"><div class="cardhead"><p>Rates are in USD. The Quote Builder retains your territory-based freight logic.</p></div><div class="tablewrap"><table><thead><tr><th>State</th><th>Destination</th><th class="number">Customer</th><th class="number">Municipality</th><th></th></tr></thead><tbody>${db.freight.map((x,i)=>`<tr><td>${esc(x.state)}</td><td>${esc(x.city)}</td><td class="number">${money(x.customer)}</td><td class="number">${money(x.municipality)}</td><td><button class="small" data-rate="${i}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`;document.querySelectorAll('[data-rate]').forEach(b=>b.onclick=()=>{const x=db.freight[+b.dataset.rate];modal('Edit freight estimate',x.city,field('Customer rate','customer',x.customer,'number','min="0"')+field('Municipality rate','municipality',x.municipality,'number','min="0"'),f=>{x.customer=+f.get('customer');x.municipality=+f.get('municipality');audit(`Freight updated: ${x.city}`);freight();toast('Freight rates saved for new quotations.')})})}
function activity(){$('#content').innerHTML=heading('Activity log','Changes made during this browser demo.')+`<section class="card">${db.logs.length?db.logs.map(l=>`<div class="logitem"><span class="miniicon">${icon('clock')}</span><div><p>${esc(l.action)}</p><small>${esc(l.by)} · ${esc(l.at)}</small></div></div>`).join(''):'<div class="empty">No changes yet. Update a price or save a quotation to see activity here.</div>'}</section>`}
login();
